/* The legacy lookup: the explicit (name, val) rows first — a
   composite key the binary search walks in the table's (name, val)
   order — then the name's default row, which answers every val the
   rows do not claim. False means neither holds the entry: the
   caller answers with the name alone, the reference's own
   pass-through with block_data dropped. `val` may be any int64 a
   numeric tag spells; a value no int32 reaches looks only at the
   defaults, where the formula names' measured answers do reach. */
struct LegacyAnswer {
    const char *to;
    size_t      to_len;
    const struct LegacyProp *props;
    size_t      nprops;
};

static bool legacy_lookup(const char *name, size_t name_len,
                          int64_t val, struct LegacyAnswer *out)
{
    if (val >= INT32_MIN && val <= INT32_MAX) {
        size_t rows = sizeof kLegacyMap / sizeof kLegacyMap[0];
        int32_t v = (int32_t)val;
        size_t lo = 0, hi = rows;
        while (lo < hi) {                   /* lower bound of (name, val) */
            size_t mid = lo + (hi - lo) / 2;
            const struct LegacyRow *r = &kLegacyMap[mid];
            int c = name_cmp_from(r->from, name, name_len);
            if (c == 0) c = (r->val < v) ? -1 : (r->val > v) ? 1 : 0;
            if (c < 0)
                lo = mid + 1;
            else
                hi = mid;
        }
        if (lo < rows) {
            const struct LegacyRow *r = &kLegacyMap[lo];
            if (name_cmp_from(r->from, name, name_len) == 0
                    && r->val == v) {
                out->to = r->to;
                out->to_len = strlen(r->to);
                out->props = r->props;
                out->nprops = r->nprops;
                return true;
            }
        }
    }
    size_t rows = sizeof kLegacyDefaults / sizeof kLegacyDefaults[0];
    size_t lo = 0, hi = rows;
    while (lo < hi) {                       /* lower bound of name */
        size_t mid = lo + (hi - lo) / 2;
        if (name_cmp_from(kLegacyDefaults[mid].from, name, name_len) < 0)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < rows
            && name_cmp_from(kLegacyDefaults[lo].from, name,
                             name_len) == 0) {
        const struct LegacyDefault *d = &kLegacyDefaults[lo];
        out->to = d->to;
        out->to_len = strlen(d->to);
        out->props = d->props;
        out->nprops = d->nprops;
        return true;
    }
    return false;
}

/* The flat lookup: the era rows above, keyed (era, name, val) in
   the order the binary search walks. `era` is the stamped block
   version the decoder wrote into the entry's `version` field —
   only the two stamps that name a measured flat era ever match;
   any other version (a real val entry with one, none in any store
   in hand) falls through to the cap chain, where D24 measured it.
   False means the era claims nothing for this cell: the caller
   answers through legacy_lookup exactly as for a versionless val
   entry, which is the reference's answer too (D25). */
static bool flat_lookup(int64_t era, const char *name, size_t name_len,
                        int64_t val, struct LegacyAnswer *out)
{
    if (val < INT32_MIN || val > INT32_MAX) return false;
    int32_t v = (int32_t)val;
    size_t rows = sizeof kFlatMap / sizeof kFlatMap[0];
    size_t lo = 0, hi = rows;
    while (lo < hi) {                   /* lower bound of (era, name, val) */
        size_t mid = lo + (hi - lo) / 2;
        const struct FlatRow *r = &kFlatMap[mid];
        int c = 0;
        if ((int64_t)r->era < era) c = -1;
        else if ((int64_t)r->era > era) c = 1;
        else c = name_cmp_from(r->from, name, name_len);
        if (c == 0) c = (r->val < v) ? -1 : (r->val > v) ? 1 : 0;
        if (c < 0)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < rows) {
        const struct FlatRow *r = &kFlatMap[lo];
        if ((int64_t)r->era == era
                && name_cmp_from(r->from, name, name_len) == 0
                && r->val == v) {
            out->to = r->to;
            out->to_len = strlen(r->to);
            out->props = r->props;
            out->nprops = r->nprops;
            return true;
        }
    }
    return false;
}

McmeTag *mcme_translate_block(McmeArena *arena, const McmeTag *entry)
{
    if (arena == NULL || entry == NULL) {
        mcme_set_error("translate: null argument");
        return NULL;
    }
    if (entry->type != MCME_TAG_Compound) {
        mcme_set_error("translate: the palette entry is a %s, not a "
                       "compound", mcme_tag_type_name(entry->type));
        return NULL;
    }

    size_t name_len = 0;
    const char *name =
        string_value(mcme_nbt_get(entry, "name"), &name_len);
    if (name == NULL) {
        mcme_set_error("translate: the palette entry has no string "
                       "'name'");
        return NULL;
    }

    /* The loader's own branch (D24, D25): the entry's SHAPE gates
       modern against legacy — `states` present, or neither field,
       is a modern entry and `version` never changes that. No
       `states` and a `val` is a pre-1.9 entry the loader spells
       `block_data`, and the entry's `version` then anchors the
       answer the way the reference anchors one: the decoder's two
       flat-era stamps answer through the flat table's deltas
       first, any other version — the real val entries in every
       store in hand carry none — and every cell without a delta
       answer through the cap chain, which is the reference's own
       answer for both (D24, D25). */
    const McmeTag *states = mcme_nbt_get(entry, "states");
    const McmeTag *val = mcme_nbt_get(entry, "val");
    if (states == NULL && val != NULL) {
        int64_t iv = 0;
        switch (val->type) {
        case MCME_TAG_Byte:
        case MCME_TAG_Short:
        case MCME_TAG_Int:
        case MCME_TAG_Long:
            iv = mcme_nbt_long_or(val, 0);
            break;
        default:
            mcme_set_error("translate: '%.*s' has a `val` that is not "
                           "a number; no Java spelling is known",
                           (int)name_len, name);
            return NULL;
        }
        struct LegacyAnswer ans;
        bool have = false;
        const McmeTag *ver = mcme_nbt_get(entry, "version");
        if (ver != NULL) {
            switch (ver->type) {
            case MCME_TAG_Byte:
            case MCME_TAG_Short:
            case MCME_TAG_Int:
            case MCME_TAG_Long:
                have = flat_lookup(mcme_nbt_long_or(ver, 0), name,
                                   name_len, iv, &ans);
                break;
            default:
                break;
            }
        }
        if (!have) have = legacy_lookup(name, name_len, iv, &ans);
        if (!have) {
            /* Neither table holds the val: the reference passes the
               block through, and mcme's unknown-block policy drops
               the state it never learned — the name, no properties. */
            return named_entry(arena, name, name_len);
        }
        McmeTag *out = named_entry(arena, ans.to, ans.to_len);
        if (out == NULL || ans.nprops == 0) return out;
        McmeTag *props = mcme_nbt_new(arena, MCME_TAG_Compound);
        if (props == NULL
                || !mcme_nbt_compound_init(arena, props, ans.nprops)) {
            return NULL;
        }
        for (size_t i = 0; i < ans.nprops; ++i) {
            McmeTag *sv = mcme_nbt_new(arena, MCME_TAG_String);
            if (sv == NULL
                    || !mcme_nbt_set_string(arena, sv, ans.props[i].val,
                                            strlen(ans.props[i].val))
                    || !mcme_nbt_compound_put(arena, props,
                                              ans.props[i].key,
                                              strlen(ans.props[i].key),
                                              sv)) {
                return NULL;
            }
        }
        if (!mcme_nbt_compound_put(arena, out, "Properties", 10,
                                   props)) {
            return NULL;
        }
        return out;
    }

    /* Redstone wire: the reference answers every Bedrock wire the
       same — four side connections and power 0 — so the map answers
       the same. Bedrock's own connection and powered states do not
       survive its universal mapping either. */
    if (strlen(kWire) == name_len
            && memcmp(name, kWire, name_len) == 0) {
        static const char *kWireProps[] = {
            "east", "north", "south", "west"
        };
        McmeTag *entry2 = named_entry(arena, name, name_len);
        McmeTag *props = mcme_nbt_new(arena, MCME_TAG_Compound);
        if (entry2 == NULL || props == NULL
                || !mcme_nbt_compound_init(arena, props, 5)) {
            return NULL;
        }
        for (size_t i = 0; i < 4; ++i) {
            McmeTag *v = mcme_nbt_new(arena, MCME_TAG_String);
            if (v == NULL
                    || !mcme_nbt_set_string(arena, v, "side", 4)
                    || !mcme_nbt_compound_put(arena, props,
                                              kWireProps[i],
                                              strlen(kWireProps[i]),
                                              v)) {
                return NULL;
            }
        }
        McmeTag *power = mcme_nbt_new(arena, MCME_TAG_String);
        if (power == NULL
                || !mcme_nbt_set_string(arena, power, "0", 1)
                || !mcme_nbt_compound_put(arena, props, "power", 5,
                                          power)
                || !mcme_nbt_compound_put(arena, entry2, "Properties",
                                          10, props)) {
            return NULL;
        }
        return entry2;
    }

    /* The name half of the map: Java spells some of these blocks
       differently, and the spelling can hang off a state value —
       red sand, a lilac, a spruce log. The table below says which
       names change and on what; an entry it does not know keeps its
       own name, which is the reference's answer too. */
    const char *jname = name;
    size_t jname_len = name_len;
    resolve_java_name(name, name_len, states, &jname, &jname_len);

    /* Everything else: the kept states, under Java's names. Any other
       state the entry carries is dropped and the block takes its Java
       default — the reference's own answer for unknown states. */
    bool is_axis_family = false;
    for (size_t s = 0;
         s < sizeof kAxisSuffixes / sizeof kAxisSuffixes[0]; ++s) {
        if (ends_with(jname, jname_len, kAxisSuffixes[s])) {
            is_axis_family = true;
            break;
        }
    }
    if (strlen(kMushroom) == jname_len
            && memcmp(jname, kMushroom, jname_len) == 0) {
        is_axis_family = false;
    }

    McmeTag *out = named_entry(arena, jname, jname_len);
    McmeTag *props = mcme_nbt_new(arena, MCME_TAG_Compound);
    if (out == NULL || props == NULL
            || !mcme_nbt_compound_init(arena, props, 2)) {
        return NULL;
    }
    size_t kept = 0;

    for (size_t i = 0; i < sizeof kKeep / sizeof kKeep[0]; ++i) {
        if (strlen(kKeep[i].block) != name_len
                || memcmp(name, kKeep[i].block, name_len) != 0) {
            continue;
        }
        const McmeTag *v = mcme_nbt_get(states, kKeep[i].from);
        if (v == NULL) continue;
        if (!mcme_nbt_compound_put(arena, props, kKeep[i].to,
                                   strlen(kKeep[i].to),
                                   (McmeTag *)v)) {
            return NULL;
        }
        ++kept;
    }

    if (is_axis_family) {
        const McmeTag *v = mcme_nbt_get(states, "pillar_axis");
        if (v == NULL) {
            /* nothing to keep */
        } else if (!mcme_nbt_compound_put(arena, props, "axis", 4,
                                          (McmeTag *)v)) {
            return NULL;
        } else {
            ++kept;
        }
    }

    if (kept > 0
            && !mcme_nbt_compound_put(arena, out, "Properties", 10,
                                      props)) {
        return NULL;
    }
    return out;
}

